using System;using System.IO;using System.Text;using System.Text.RegularExpressions;using System.Diagnostics;using System.Drawing;using System.Windows.Forms;using System.Threading.Tasks;using System.Collections.Generic;using System.Web.Script.Serialization;using System.Security.Cryptography;
class SeiTransportTest:Form{
 readonly string root=AppDomain.CurrentDomain.BaseDirectory;Dictionary<string,object> cfg;TextBox key,channel,log;Label status;CheckBox stopped;Button start,local,best,low,stop;Process publisher,runningTool;Timer timer;bool busy;volatile bool closing;DateTime startedAt;JavaScriptSerializer json=new JavaScriptSerializer();
 string PathFor(string n){return System.IO.Path.Combine(root,n);}string Tool(string n){return (string)cfg[n];}static string Q(string s){if(s.Contains("\"")||s.Contains("\r")||s.Contains("\n"))throw new Exception("Недопустимый символ в пути");return "\""+s+"\"";}
 bool FixtureOk(){using(var sha=SHA256.Create())using(var f=File.OpenRead(PathFor("stream.mp4")))return BitConverter.ToString(sha.ComputeHash(f)).Replace("-","").ToLowerInvariant()==(string)cfg["sha256"];}
 bool Ready(){return File.Exists(Tool("ffmpeg"))&&File.Exists(Tool("node"))&&File.Exists(Tool("streamlink"))&&File.Exists(PathFor("scripts/check-sei-retention.mjs"))&&File.Exists(PathFor("shared/covert-sei.mjs"))&&File.Exists(PathFor("shared/covert-primitives.mjs"))&&FixtureOk();}
 void Say(string s){log.AppendText(s+Environment.NewLine);}
 Button Btn(string label,int x,int y,int width){var b=new Button{Text=label,Left=x,Top=y,Width=width,Height=44,FlatStyle=FlatStyle.Flat,BackColor=Color.FromArgb(65,38,89),ForeColor=Color.White};Controls.Add(b);return b;}
 Label LabelAt(string t,int x,int y,int w,int h){var l=new Label{Text=t,Left=x,Top=y,Width=w,Height=h,ForeColor=Color.FromArgb(218,202,237)};Controls.Add(l);return l;}
 public SeiTransportTest(){cfg=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(PathFor("runtime.json")));Text="Freecam · Twitch transport test";ClientSize=new Size(900,740);BackColor=Color.FromArgb(16,12,23);ForeColor=Color.White;Font=new Font("Segoe UI",10);FormBorderStyle=FormBorderStyle.FixedSingle;MaximizeBox=false;
 var h=LabelAt("FREECAM / ПРОВЕРКА ДОСТАВКИ TWITCH",24,20,850,38);h.Font=new Font("Segoe UI",18,FontStyle.Bold);h.ForeColor=Color.FromArgb(199,154,255);
 LabelAt("Тестовый ролик → Twitch → запись зрителя → проверка SEI. OBS в этом тесте не передаёт видео.",24,68,850,45);
 LabelAt("1. Имя своего канала (без ссылки)",24,116,600,26);channel=new TextBox{Left=24,Top=144,Width=410};Controls.Add(channel);
 LabelAt("2. Ключ трансляции Twitch — НЕ пароль OBS",24,184,700,26);key=new TextBox{Left=24,Top=212,Width=850,UseSystemPasswordChar=true};Controls.Add(key);
 LabelAt("Ключ не сохраняется в файлы и отчёты. Передаётся локальному FFmpeg для входа в Twitch по RTMPS.",24,248,850,30);
 stopped=new CheckBox{Text="Я остановил текущий эфир в OBS. Следующая кнопка начнёт ПУБЛИЧНЫЙ тест.",Left=24,Top=284,Width=850,Height=32};Controls.Add(stopped);
 local=Btn("Локальная проверка (без эфира)",24,332,280);start=Btn("Начать публичный тест · 120 с",316,332,340);stop=Btn("Остановить эфир",668,332,206);
 best=Btn("Записать и проверить лучшее качество",24,390,425);low=Btn("Записать и проверить 720p",462,390,412);
 status=LabelAt("Сначала выполните локальную проверку. Эфир сам не запускается.",24,450,850,42);log=new TextBox{Left=24,Top=500,Width=850,Height=180,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,BackColor=Color.FromArgb(28,20,38),ForeColor=Color.FromArgb(230,217,245)};Controls.Add(log);
 var results=Btn("Открыть результаты",24,692,240);results.Height=32;results.Click+=(s,e)=>{Directory.CreateDirectory(PathFor("results"));Process.Start(new ProcessStartInfo(PathFor("results")){UseShellExecute=true});};
 local.Click+=async(s,e)=>await Guard(LocalCheck);start.Click+=(s,e)=>Publish();stop.Click+=(s,e)=>StopPublisher();best.Click+=async(s,e)=>await Guard(()=>CaptureDelivery("best"));low.Click+=async(s,e)=>await Guard(()=>CaptureDelivery("720p60,720p"));
 timer=new Timer{Interval=500};timer.Tick+=(s,e)=>{if(publisher!=null&&!publisher.HasExited&&(DateTime.UtcNow-startedAt).TotalSeconds>=120)StopPublisher();if(publisher!=null&&publisher.HasExited){int code=publisher.ExitCode;publisher.Dispose();publisher=null;status.Text=code==0?"Тестовый эфир завершён.":"Отправка завершилась с ошибкой (код "+code+"). Проверьте ключ и соединение.";key.Clear();}};timer.Start();FormClosing+=(s,e)=>{closing=true;StopPublisher();try{if(runningTool!=null&&!runningTool.HasExited)runningTool.Kill();}catch{}};
 }
 async Task Guard(Func<Task> work){if(busy)return;busy=true;local.Enabled=best.Enabled=low.Enabled=false;try{if(!Ready())throw new Exception("Файлы стенда изменились или инструменты недоступны. Пересоберите стенд.");await work();}catch(Exception ex){Say(ex.Message);status.Text="Действие не завершено. Ключ повторно не выводится.";}finally{busy=false;local.Enabled=best.Enabled=low.Enabled=true;}}
 class Result{public int Code;public string Output;}
 Task<Result> Run(string exe,string args,int timeout=90000){return Task.Run(()=>{using(var p=new Process{StartInfo=new ProcessStartInfo(exe,args){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,WorkingDirectory=root}}){if(closing)throw new Exception("Стенд закрывается");runningTool=p;p.StartInfo.EnvironmentVariables["PATH"]=System.IO.Path.GetDirectoryName(Tool("ffmpeg"))+";"+Environment.GetEnvironmentVariable("PATH");p.Start();if(closing){p.Kill();throw new Exception("Стенд закрывается");}var output=p.StandardOutput.ReadToEndAsync();var errors=p.StandardError.ReadToEndAsync();if(!p.WaitForExit(timeout)){p.Kill();throw new Exception("Превышено время ожидания. Попробуйте, когда на канале виден тестовый ролик.");}Task.WaitAll(output,errors);runningTool=null;return new Result{Code=p.ExitCode,Output=output.Result};}});}
 async Task<int> Check(string file,string label){var r=await Run(Tool("node"),Q(PathFor("scripts/check-sei-retention.mjs"))+" "+Q(file));if(r.Code!=0)throw new Exception("Не удалось прочитать AVC-видео. Это не доказательство потери SEI.");var data=json.Deserialize<Dictionary<string,object>>(r.Output);int n=Convert.ToInt32(data["freecamPackets"]);var text=label+": найдено пакетов Freecam: "+n+".";Say(text);File.WriteAllText(file+".report.json",r.Output,Encoding.UTF8);if(n>0)Say("Данные сохранились в этой записи. Это положительный результат для выбранного качества.");else Say("0 пакетов — ещё не вердикт. Проверьте: записан наш ролик, нет рекламы, выбран Source/нужное качество.");return n;}
 async Task LocalCheck(){status.Text="Локальная проверка MP4 → FLV без перекодирования…";Directory.CreateDirectory(PathFor("results"));string file=PathFor("results/local-copy.flv");var r=await Run(Tool("ffmpeg"),"-hide_banner -loglevel error -y -i "+Q(PathFor("stream.mp4"))+" -map 0 -c copy -f flv "+Q(file));if(r.Code!=0)throw new Exception("Локальная перепаковка не прошла.");int count=await Check(file,"Локальная проверка");if(count!=96)throw new Exception("Локальная проверка не обнаружила все 96 пакетов. Не запускайте эфир.");status.Text="Локальная проверка завершена. Эфир не запускался.";}
 void Publish(){try{if(publisher!=null&&!publisher.HasExited){Say("Тестовый эфир уже запущен.");return;}if(!Ready())throw new Exception("Стенд не прошёл проверку файлов.");if(!stopped.Checked)throw new Exception("Остановите эфир OBS и отметьте подтверждение выше.");string secret=key.Text.Trim();if(!Regex.IsMatch(secret,@"^live_[A-Za-z0-9_-]{10,}$"))throw new Exception("Вставьте основной ключ трансляции Twitch, начинающийся с live_.");string destination="rtmps://ingest.global-contribute.live-video.net/app/"+secret;
 var info=new ProcessStartInfo(Tool("ffmpeg"),"-hide_banner -loglevel quiet -re -stream_loop -1 -i "+Q(PathFor("stream.mp4"))+" -t 120 -map 0:v:0 -map 0:a:0 -c copy -f flv -flvflags no_duration_filesize -progress pipe:1 -rw_timeout 10000000 -tls_verify 1 "+Q(destination)){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,RedirectStandardInput=true,WorkingDirectory=root};publisher=new Process{StartInfo=info};publisher.OutputDataReceived+=(s,e)=>{if(e.Data!=null&&e.Data.StartsWith("out_time_us=")){long t;if(long.TryParse(e.Data.Substring(12),out t)&&IsHandleCreated)BeginInvoke((Action)(()=>status.Text="Передано примерно "+(t/1000000)+" с из 120. Откройте канал и убедитесь, что виден наш ролик."));}};publisher.ErrorDataReceived+=(s,e)=>{};publisher.Start();startedAt=DateTime.UtcNow;publisher.BeginOutputReadLine();publisher.BeginErrorReadLine();key.Clear();status.Text="Подключение к Twitch…";Say("Запущен публичный тест (до 120 секунд), копирование видео и звука без перекодирования.");
 }catch(Exception ex){StopPublisher();Say(ex.Message);}}
 void StopPublisher(){if(publisher==null)return;try{if(!publisher.HasExited){publisher.StandardInput.WriteLine("q");if(!publisher.WaitForExit(1500))publisher.Kill();}}catch{}try{publisher.Dispose();}catch{}publisher=null;status.Text="Тестовый эфир остановлен.";key.Clear();}
 async Task CaptureDelivery(string quality){string login=channel.Text.Trim();if(!Regex.IsMatch(login,@"^[A-Za-z0-9_]{3,25}$"))throw new Exception("Укажите только имя своего канала, например my_channel.");Directory.CreateDirectory(PathFor("results"));string file=PathFor("results/delivery-"+(quality=="best"?"best":"720p")+"-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".ts");status.Text="Запись доставки Twitch: около 20 секунд, ожидание может занять дольше…";
 var r=await Run(Tool("streamlink"),"--no-config --loglevel error --stream-segmented-duration 20 --stream-segment-timeout 15 --output "+Q(file)+" "+Q("https://www.twitch.tv/"+login)+" "+Q(quality),90000);if(r.Code!=0||!File.Exists(file)||new FileInfo(file).Length<1000)throw new Exception("Запись Twitch не получена. Проверьте канал/наличие эфира. Возможны ограничения доступа Streamlink; это не результат проверки SEI.");await Check(file,quality=="best"?"Лучшее доступное качество (не гарантированно Source)":"720p");status.Text="Запись и отчёт сохранены в папке results. Для Source сверьте качество с плеером Twitch.";
 }
 [STAThread]static int Main(string[] args){try{Application.EnableVisualStyles();var form=new SeiTransportTest();if(args.Length>0&&args[0]=="--self-test")return form.Ready()?0:2;if(args.Length>0&&args[0]=="--offline-check"){int result=1;form.Opacity=0;form.ShowInTaskbar=false;form.Shown+=async(s,e)=>{try{await form.LocalCheck();result=0;File.WriteAllText(form.PathFor("results/offline-application-check.txt"),form.log.Text,Encoding.UTF8);}catch{result=1;}finally{form.Close();}};Application.Run(form);return result;}if(args.Length>0&&args[0]=="--preview"){using(var bitmap=new Bitmap(form.ClientSize.Width,form.ClientSize.Height))using(var graphics=Graphics.FromImage(bitmap)){graphics.Clear(form.BackColor);foreach(Control control in form.Controls){var handle=control.Handle;using(var child=new Bitmap(control.Width,control.Height)){control.DrawToBitmap(child,new Rectangle(0,0,control.Width,control.Height));graphics.DrawImageUnscaled(child,control.Left,control.Top);}}bitmap.Save(form.PathFor("preview.png"));}return 0;}Application.Run(form);return 0;}catch{if(args.Length==0)MessageBox.Show("Не удалось открыть стенд. Запускайте EXE из подготовленной папки с runtime.json и stream.mp4.","Freecam");return 1;}}
}
